#ifndef PUNTO_H
#define PUNTO_H

typedef struct {
  double x;
  double y;
} TPunto;

TPunto crear(double x, double y);
TPunto origen();
double distancia(TPunto a, TPunto b);
TPunto puntoMedio(TPunto a, TPunto b);
void mostrar(TPunto p);

#endif

#include <stdio.h>
#include <math.h>
#include "punto.h"

TPunto crear(double x, double y) {
  TPunto p;

  p.x = x;
  p.y = y;
  return p;
}

TPunto origen() {
  return crear(0, 0);
}

double distancia(TPunto a, TPunto b) {
  double dx = a.x - b.x;
  double dy = a.y - b.y;

  return sqrt(dx * dx + dy * dy);
}

TPunto puntoMedio(TPunto a, TPunto b) {
  return crear((a.x + b.x) / 2, (a.y + b.y) / 2);
}

void mostrar(TPunto p) {
  printf("(%.2f, %.2f)", p.x, p.y);
}

