  TPunto pts[MAX];
  double x, y;
  double total = 0;
  int n;

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%lf", &x);
    scanf("%lf", &y);
    pts[i] = crear(x, y);
  }
  for (int i = 0; i < n - 1; i++) {
    total = total + distancia(pts[i], pts[i + 1]);
  }
  printf("%.2f", total);
  return 0;
}

