#include <stdio.h>
#include "punto.h"

#define MAX 10

int main() {
  TPunto pts[MAX];
  double x, y;
  double menor;
  int a = 0;
  int b = 1;
  int n;

  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%lf", &x);
    scanf("%lf", &y);
    pts[i] = crear(x, y);
  }
  menor = distancia(pts[0], pts[1]);
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (distancia(pts[i], pts[j]) < menor) {
        menor = distancia(pts[i], pts[j]);
        a = i;
        b = j;
      }
    }
  }
  mostrar(pts[a]);
  printf(" ");
  mostrar(pts[b]);
  printf(" %.2f", menor);
  return 0;
}
